"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["59788"],{19119(e,t,o){o.d(t,{Ay:()=>h,RM:()=>i});var n=o(74848),s=o(28453),r=o(66422);let i=[{value:"Replies",id:"replies",level:3}];function a(e){let t={blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"this-ids-one-post-made-kong-qingdong-so-furious-he-replied-twice",children:"This ID's One Post Made Kong Qingdong So Furious He Replied Twice"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2006/9/24 9:55:02"}),"\n"]}),"\n",(0,n.jsxs)("div",{style:{textAlign:"center"},children:[(0,n.jsx)("img",{src:(0,r.Ay)("/img/poems/kongqdreply/1.jpeg")}),(0,n.jsx)("br",{}),(0,n.jsx)("br",{})]}),"\n",(0,n.jsx)(t.p,{children:"This ID's one post \u2014 \"Kong Qingdong, don't embarrass Peking University, let this ID teach you to write poetry!\" \u2014 made Kong Qingdong so furious he fired off two replies, quoted below:"}),"\n",(0,n.jsx)(t.p,{children:"Kong Qingdong replied on 2006/09/23 00:41:06:"}),"\n",(0,n.jsx)(t.p,{children:"Your poems have decent command of words, but no true feeling \u2014 just piling up concepts, nothing more than metrically correct empty bombast. Especially your tone \u2014 the classic face of a petty villain. You think you're worthy of discussing history? But I won't insult you by saying you embarrass anyone \u2014 you're just a scoundrel who can write poems! When I was writing poems at your level, your whole family hadn't been born yet! You dare discuss poetry with me? Shameless!"}),"\n",(0,n.jsx)(t.p,{children:"2006-09-23 00:51:53"}),"\n",(0,n.jsx)(t.p,{children:"To that fake Zen, true villain:"}),"\n",(0,n.jsx)(t.p,{children:"Your poems have decent command of words, but no true feeling \u2014 just piling up concepts, nothing more than metrically correct empty bombast. Your poems say nothing. Your understanding of regulated verse is at a middle-school level \u2014 what you said is simply wrong. Do you even know what parallel couplets are? You haven't even understood my poems. Especially your tone \u2014 the classic face of a petty villain. You think you're worthy of discussing history? But I won't insult you by saying you embarrass anyone \u2014 you're just a scoundrel who can barely write poems! When I was writing poems at your level, your whole family hadn't been born yet! You dare discuss poetry with me? Shameless!"}),"\n",(0,n.jsx)(t.p,{children:'Good grief, Peking University Chinese Department \u2014 how could you have sunk this low? Better scrub the words "Peking University" off your name! Look at the hideous Chinese your so-called celebrity has churned out. This ID once coined a famous saying: "If you\'re a hooligan, who do you fear? Hooligans fear only female hooligans!" When it comes to those playing hooligan, whether they\'re from the Chinese Department or the "Slit-Throat Department," the result is the same \u2014 they\'re all defeated generals under this ID\'s command.'}),"\n",(0,n.jsx)(t.p,{children:"The two replies came ten minutes apart. On the surface, the latter is the 2.0 version of the former, but one shouldn't look only at the latter \u2014 the differences between them better expose the secrets lurking in his heart. The former is like a frog's reflex after being prodded, no different from those online sock puppets whose sole joy is hurling abuse \u2014 basically the \"you're trash, I'm the man\" template, expressed with uniformly crude brutality. This type of reply mainly originates from involuntary spasms below the lower abdomen."}),"\n",(0,n.jsx)(t.p,{children:'The latter must have involved some activity above the lower abdomen, yielding this additional content: "To that fake Zen, true villain:" + "Your poems say nothing. Your understanding of regulated verse is at a middle-school level \u2014 what you said is simply wrong. Do you even know what parallel couplets are? You haven\'t even understood my poems." + "But I won\'t insult you by saying you embarrass anyone \u2014 you\'re just a scoundrel who can barely write poems!" The most notable feature here is the addition of much professional posturing \u2014 or rather, the flaunting of professional credentials. This professionalized polish makes the latter\'s affected pretense even more stomach-churning for earthlings than the former\'s crude directness.'}),"\n",(0,n.jsx)(t.p,{children:"Analysis point by point:"}),"\n",(0,n.jsxs)(t.p,{children:["To that fake Zen, true villain:",(0,n.jsx)("br",{}),"\n===============",(0,n.jsx)("br",{}),'\nZen is neither false nor true, borrowing neither mind nor matter \u2014 how could the likes of you comprehend it? As for "true villain" \u2014 someone who prefers playing the "hypocrite gentleman" would naturally disdain the "true villain," and that\'s all there is to it. Everyone can see through this!']}),"\n",(0,n.jsxs)(t.p,{children:["Your poetry has decent command of words, but no true feeling \u2014 just piling up concepts, nothing more than metrically correct empty bombast. Your poems say nothing.",(0,n.jsx)("br",{}),"\n=====================",(0,n.jsx)("br",{}),'\nDoes this ID\'s command of poetic words need your commentary? What was written here on-screen is already more than you can handle! Unlike certain people who can\'t even manage proper meter and have to claim they\'re "breaking free from metrical constraints" as an excuse for their embarrassment! Did meter ever constrain Du Fu? Does meter ever constrain this ID? As for what this ID composed on-screen following the rhyme \u2014 "Heaven and earth have tears \u2014 they cannot form a poem; blood waters the hills, spirits and ghosts gallop. For a hundred li, fresh dead bones still overflow; a thousand years, living flesh is wounded once again. A boat can carry or capsize \u2014 cry that the people matter; heaven grants shade or shine \u2014 awaken the nation from its baseness. The vast wild lies windless, sinking into eternal night; a lone star like the moon, its spirit towering to the brow." \u2014 whether this is "no true feeling, just piling up concepts, nothing more than metrically correct empty bombast" is for the public to judge, provided you can even understand it. For those who couldn\'t understand it at all, naturally they can only say "your poems say nothing" \u2014 thus exposing their own disgrace!']}),"\n",(0,n.jsxs)(t.p,{children:["Your understanding of regulated verse is at a middle-school level \u2014 what you said is simply wrong. Do you even know what parallel couplets are? You haven't even understood my poems.",(0,n.jsx)("br",{}),"\n======================",(0,n.jsx)("br",{}),"\nDu Fu never \"understood\" regulated verse \u2014 he just wrote it, and this ID is the same. The work decides everything. Associate Professor Kong's \"At twenty-five, yearning to daub a poem, gut-wrung, the brush won't gallop. Old grudges like sores ache in wind and rain, new feuds like gashes rend the skin. Q\xedn Qi\xf3ng could swallow a thousand tears, Y\xe8 T\u01D0ng \u2014 why sing one word of baseness? Bright sun lights the lamp to fight the long night, for now the sword is sheathed, awaiting brows held high.\" \u2014 this Cultural Revolution slogan-style stuff doesn't even qualify as rough and rugged; it's simply laughable the moment it's put to paper. Take note: everything you wrote, this ID covered in the rhyme-matching poem; what you wanted to write but couldn't, this ID also wrote; what you never even thought of, this ID wrote that too. You didn't know? How pitiful!"]}),"\n",(0,n.jsxs)(t.p,{children:["Especially your tone \u2014 the classic face of a petty villain. You think you're worthy of discussing history? But I won't insult you by saying you embarrass anyone \u2014 you're just a scoundrel who can barely write poems!",(0,n.jsx)("br",{}),"\n=====================================",(0,n.jsx)("br",{}),'\nHistory is not for discussing \u2014 history is for violating. And history keeps proving that those who wear the mask of a gentleman are the most dangerous. As for that last line \u2014 "But I won\'t insult you by saying you embarrass anyone \u2014 you\'re just a scoundrel who can barely write poems!" \u2014 following the principle of "courtesy demands reciprocity" so beloved by those who wear the gentleman\'s mask, this naturally must be returned to Associate Professor Kong!']}),"\n",(0,n.jsxs)(t.p,{children:["When I was writing poems at your level, your whole family hadn't been born yet! You dare discuss poetry with me? Shameless!",(0,n.jsx)("br",{}),"\n=====================",(0,n.jsx)("br",{}),"\nAssociate Professor Kong truly lives up to his ancestry as a descendant of the great Master Kong \u2014 he finally managed to speak some truth. Associate Professor Kong is now in his forties. In all of Associate Professor Kong's 40-odd years of existence, there has never been a time when this ID's entire family was unborn. Therefore, Associate Professor Kong's claim that \"When I was writing poems at your level, your whole family hadn't been born yet\" can only refer to an event that never occurred \u2014 which is to say, Associate Professor Kong admits: he has never achieved this ID's level of poetry, not even the level of this ID's casual on-screen rhyme-matching, not once in his entire life. Honesty deserves encouragement. As for Associate Professor Kong's parting shot \"You dare discuss poetry with me? Shameless!\" \u2014 like the habitual petulance of all middle-aged men, just let him be!"]}),"\n",(0,n.jsx)(t.p,{children:'Finally, would Associate Professor Kong please lead everyone in chanting in unison: "If you\'re a hooligan, who do you fear? Hooligans fear only female hooligans!" \u2014 368 times! Thank you!'}),"\n",(0,n.jsx)(t.h3,{id:"replies",children:"Replies"}),"\n",(0,n.jsxs)("div",{class:"blog-comment",children:[(0,n.jsxs)(t.p,{children:[(0,n.jsx)("span",{class:"blog-comment-chan",children:"\u7F20\u4E2D\u8BF4\u7985"})," 2006/9/24 10:05:05",(0,n.jsx)("br",{})]}),(0,n.jsx)(t.p,{children:"Appendix:"}),(0,n.jsx)(t.p,{children:"Kong Qingdong, you embarrass the Chinese Department, but don't embarrass Peking University!"}),(0,n.jsx)(t.p,{children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\nRecently, as autumn approaches, the weather is getting dry. Everyone on earth hopes for a bit more moisture, and this fuss over poetry has heated up. Poet Zhao made a splash that shook the world, drawing a torrent of saliva and greatly increasing global humidity. But compared to Associate Professor Kong Qingdong, Poet Zhao is nothing \u2014 when Poet Kong appeared, the greenhouse effect instantly became the wetroom effect, even the sun turned into the moon, and fluids flowed without end."}),(0,n.jsx)(t.p,{children:'Although Poet Kong ("the Wet One") has made such formidable contributions, this ID must still thunder: Kong Qingdong, don\'t embarrass Peking University! Look at what you\'ve written \u2014 you even dare write classical poetry! You think because you can get "wet" you can write verse? You think because your ancestor said "Without studying poetry, one cannot speak," that makes you a poet? Everyone, look at what this man has written \u2014 what a disgrace! Quoted below:'}),(0,n.jsx)(t.p,{children:"Self-Birthday Poem at Twenty-Five"}),(0,n.jsx)(t.p,{children:"Kong Qingdong"}),(0,n.jsxs)(t.p,{children:["At twenty-five, yearning to daub a poem, gut-wrung, the brush won't gallop. ",(0,n.jsx)("br",{}),"\nOld grudges like sores ache in wind and rain, new feuds like gashes rend the skin. ",(0,n.jsx)("br",{}),"\nQ\xedn Qi\xf3ng could swallow a thousand tears, Y\xe8 T\u01D0ng \u2014 why sing one word of baseness? ",(0,n.jsx)("br",{}),"\nBright sun lights the lamp to fight the long night, for now the sword is sheathed, awaiting brows held high."]}),(0,n.jsx)(t.p,{children:'What on earth is this? Parallel couplets repeated, the meter is wrong \u2014 is "Bright sun lights the lamp to fight the long night" even a proper regulated line? And "a thousand tears" dares to pair with "one word of baseness"? As for the verses themselves, they\'re not only bland and tasteless but childish beyond belief; the rhyme scheme is a mess, and even basic diction is problematic. If this ID were still writing such stuff at age 25, this ID would be too embarrassed to claim Peking University \u2014 and if I did claim it, there\'d be only one path: straight into Weiming Lake. Chinese Department, you still have the nerve to call yourselves Peking University\'s most formidable department?'}),(0,n.jsx)(t.p,{children:"Peking University \u2014 though the futures market beside me is wildly fluctuating, this ID must still weep bitterly for you, for who made you so important in this ID's life! For the sake of Peking University, this ID now composes on-screen a rhyme-matching poem to this so-called Chinese Department Associate Professor Kong Qingdong's \"Self-Birthday Poem at Twenty-Five\" \u2014 let the quality speak for itself."}),(0,n.jsx)(t.p,{children:'Rhyme-Matching Kong Qingdong\'s "Self-Birthday Poem at Twenty-Five," No. 1:'}),(0,n.jsxs)(t.p,{children:["Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\nHeaven and earth have tears \u2014 they cannot form a poem; blood waters the hills, spirits and ghosts gallop. ",(0,n.jsx)("br",{}),"\nFor a hundred li, fresh dead bones still overflow; a thousand years, living flesh is wounded once again. ",(0,n.jsx)("br",{}),"\nA boat can carry or capsize \u2014 cry that the people matter; heaven grants shade or shine \u2014 awaken the nation from its baseness. ",(0,n.jsx)("br",{}),"\nThe vast wild lies windless, sinking into eternal night; a lone star like the moon, its spirit towering to the brow."]}),(0,n.jsx)(t.p,{children:"Good heavens \u2014 the original poem's rhyme scheme is utter garbage. Associate Professor Kong was basically just padding rhymes. Of course, even such a garbage rhyme scheme can't stump this ID. Associate Professor Kong, learn a thing or two \u2014 you can embarrass the Chinese Department, but please don't embarrass Peking University!"})]})]})}function h(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(a,{...e})}):a(e)}},29681(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>a,contentTitle:()=>h,toc:()=>d,assets:()=>l});var n=JSON.parse('{"id":"poems/kongqdreply","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/poems/kongqdreply.md","sourceDirName":"poems","slug":"/poems/kongqdreply","permalink":"/en/poems/kongqdreply","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"kongqdreply","title":"","hide_table_of_contents":true,"sidebar_label":"One Post by this ID, and Kong Qingdong Furiously Fired Back Two Replies. (2006/9/24 9:55:02)"},"sidebar":"poemsSidebar","previous":{"title":"Kong Qingdong, Don\'t Disgrace Peking University\u2014Let this ID Teach You to Write Poetry! (2006/9/22 23:44:31)","permalink":"/en/poems/tokongqd"},"next":{"title":"Following a Friend\'s Rhyme Scheme to Celebrate the Double Festival (2006/10/1 14:03:53)","permalink":"/en/poems/doublefestival"}}'),s=o(74848),r=o(28453),i=o(19119);let a={id:"kongqdreply",title:"",hide_table_of_contents:!0,sidebar_label:"One Post by this ID, and Kong Qingdong Furiously Fired Back Two Replies. (2006/9/24 9:55:02)"},h,l={},d=[...i.RM];function u(e){return(0,s.jsx)(i.Ay,{})}function c(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,t,o){o.d(t,{R:()=>i,x:()=>a});var n=o(96540);let s={},r=n.createContext(s);function i(e){let t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);